---@param productInfoList table
function ActivityDirectDrawComponent:FillDirectDrawMallProductList(productInfoList)
    if self._activityDirectDrawMallProductDojoList then
        for i, dojo in ipairs(self._activityDirectDrawMallProductDojoList) do
            dojo:Delete()
        end
        self._activityDirectDrawMallProductDojoList = nil
    end

    self._activityDirectDrawMallProductDojoList = {}
    self._activityDirectDrawMallProductDojoHash = {}
    for i, productInfo in ipairs(checkTable(productInfoList)) do
        ---@type ActivityDirectDrawMallProductDojo
        local dojo = ActivityDirectDrawMallProductDojo.New()
        dojo:Fill(productInfo)
        self._activityDirectDrawMallProductDojoHash[checkString(dojo.productId)] = dojo
        table.insert(self._activityDirectDrawMallProductDojoList, dojo)
    end
end

function ActivityDirectDrawComponent:UpdateMallProductList()
    local requestData = { activityUuid = self._activityDojo.id }
    GameUtils.Request(Interfaces.OrientationCallMall, requestData, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        local list = jsonData.orientationCallProductInfo
        for i, product in ipairs(list) do
            local productId = product.productId
            self._activityDirectDrawMallProductDojoHash[checkString(productId)]:Fill(product)
        end
        Events.Broadcast(Constants.EventNames.ActivityDirectDrawShoppingMallDataUpdateReq)
    end)
end

function ActivityDirectDrawComponent:GetMallProductList()
    return checkTable(self._activityDirectDrawMallProductDojoList)
end

